const { holdPayment, capturePayment, releaseHold, findRider, notify } =
  proxyActivities<typeof activities>({ startToCloseTimeout: '30 seconds' });
export const accepted = defineSignal('accepted');

export async function placeOrder(o: Order): Promise<void> {
  let isAccepted = false;
  setHandler(accepted, () => { isAccepted = true; });

  const hold = await holdPayment(o.id, o.total);           // retried by Temporal
  if (!(await condition(() => isAccepted, '5 minutes'))) {
    await releaseHold(hold);                                 // the undo
    await notify(o.customerId, 'Restaurant did not accept; hold released');
    return;
  }
  await capturePayment(hold);
  const rider = await findRider(o.id);                       // may take minutes
  await notify(o.customerId, `On the way with ${rider.name}`);
}
